From 0169b7ff5308f036835d588c44294e6c81352a11 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:51:56 +0100
Subject: [PATCH] applets/systemmonitor: show sensor values in the tooltip

The tooltip only showed the total sensor, so widgets without one never
showed a value, and new widgets showed nothing until a restart. Also
list the high-priority sensors and signal when the controller is set.

BUG: 445570
---
 .../package/contents/ui/main.qml              | 23 ++++++++++++++++++-
 .../systemmonitor/systemmonitor.cpp           |  1 +
 .../systemmonitor/systemmonitor.h             |  3 ++-
 3 files changed, 25 insertions(+), 2 deletions(-)

diff --git a/applets/systemmonitor/systemmonitor/package/contents/ui/main.qml b/applets/systemmonitor/systemmonitor/package/contents/ui/main.qml
index 357c9b18fa..3c586b4d45 100644
--- a/applets/systemmonitor/systemmonitor/package/contents/ui/main.qml
+++ b/applets/systemmonitor/systemmonitor/package/contents/ui/main.qml
@@ -60,7 +60,18 @@ PlasmoidItem {
     preferredRepresentation: Plasmoid.formFactor === PlasmaCore.Types.Planar ? fullRepresentation : null

     Plasmoid.title: Plasmoid.faceController?.title || i18n("System Monitor")
-    toolTipSubText: totalSensor.sensorId ? i18nc("Sensor name: value", "%1: %2", totalSensor.name, totalSensor.formattedValue) : ""
+    toolTipSubText: {
+        const sensors = [totalSensor];
+        for (let i = 0; i < highPrioritySensors.count; ++i) {
+            const sensor = highPrioritySensors.objectAt(i);
+            if (sensor && sensor.sensorId !== totalSensor.sensorId) {
+                sensors.push(sensor);
+            }
+        }
+        return sensors.filter(sensor => sensor.sensorId)
+            .map(sensor => i18nc("Sensor name: value", "%1: %2", Plasmoid.faceController.sensorLabels[sensor.sensorId] || sensor.name, sensor.formattedValue))
+            .join("\n")
+    }

     compactRepresentation: CompactRepresentation {
     }
@@ -80,6 +91,16 @@ PlasmoidItem {
         updateRateLimit: Plasmoid.faceController?.updateRateLimit
     }

+    Instantiator {
+        id: highPrioritySensors
+        model: (Plasmoid.faceController?.highPrioritySensorIds ?? []).slice(0, 8)
+        delegate: Sensors.Sensor {
+            required property string modelData
+            sensorId: modelData
+            updateRateLimit: Plasmoid.faceController?.updateRateLimit
+        }
+    }
+
     MouseArea {
         anchors.fill: parent
         acceptedButtons: Qt.MiddleButton
diff --git a/applets/systemmonitor/systemmonitor/systemmonitor.cpp b/applets/systemmonitor/systemmonitor/systemmonitor.cpp
index d30295d937..a66d2faeaa 100644
--- a/applets/systemmonitor/systemmonitor/systemmonitor.cpp
+++ b/applets/systemmonitor/systemmonitor/systemmonitor.cpp
@@ -44,6 +44,7 @@ void SystemMonitor::init()
     // We have initialized our preset, subsequent calls should use the root-plugin id
     config().writeEntry("CurrentPreset", "org.kde.plasma.systemmonitor");
     m_sensorFaceController->loadPreset(preset);
+    Q_EMIT faceControllerChanged();
 }

 KSysGuard::SensorFaceController *SystemMonitor::faceController() const
diff --git a/applets/systemmonitor/systemmonitor/systemmonitor.h b/applets/systemmonitor/systemmonitor/systemmonitor.h
index addc3614b0..86c5638b4c 100644
--- a/applets/systemmonitor/systemmonitor/systemmonitor.h
+++ b/applets/systemmonitor/systemmonitor/systemmonitor.h
@@ -25,7 +25,7 @@ class SystemMonitor : public Plasma::Applet
 {
     Q_OBJECT

-    Q_PROPERTY(KSysGuard::SensorFaceController *faceController READ faceController CONSTANT)
+    Q_PROPERTY(KSysGuard::SensorFaceController *faceController READ faceController NOTIFY faceControllerChanged)

 public:
     SystemMonitor(QObject *parent, const KPluginMetaData &data, const QVariantList &args);
@@ -35,6 +35,7 @@ public:
     Q_INVOKABLE void openSystemMonitor();

     KSysGuard::SensorFaceController *faceController() const;
+    Q_SIGNAL void faceControllerChanged();

     // Workaround for Bug 424458, when reusing the controller/item things break in ConfigAppearance
     Q_INVOKABLE KSysGuard::SensorFaceController *workaroundController(QQuickItem *context) const;
